import React, { useState } from "react";
import API from "./api";
import './Enter.css';
import { useAuth } from '../authcontext';
import { useNavigate } from 'react-router-dom';

const Enter = () => {
  const navigate = useNavigate();
  const { login } = useAuth();
  const [action, setAction] = useState("register");
  const [formData, setFormData] = useState({
    email: "",
    password: "",
  });
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      if (action === "register") {
        setLoading(true);
        await API.post("register/", formData);
        setLoading(false);
        setMessage("Вы успешно зарегистрировались. Проверьте вашу почту для подтверждения");
        setError("");
      } else if (action === "login") {
        const response = await API.post("login/", formData);
        const token = response.data.token;
        localStorage.setItem("refresh", response.data.refresh);
        setMessage("Вы успешно вошли!");
        setError("");
        const userData = {email : formData.email, token : token};
        login(userData);
        navigate('/dashboard');
      }
    } catch (err) {
      setLoading(false);
      setError(err.response?.data?.detail || "Произошла ошибка");
      setMessage("");
    }
  };

  return (
    <div class="main">
        <title>{action === "register" ? "Регистрация" : "Вход"}</title>
        <header class="main_box">
                <a class="name" href="/">Сайт с олимпиадами</a>
                <a class="enter" href="enter">Вход/Регистрация</a>
                <a class="search" href="search" style={{float : "right"}}><span>Поиск по фильтрам</span></a> 
        </header>
        <h1>{action === "register" ? "Регистрация" : "Вход"}</h1>
        <button class="btn" onClick={() => (setAction("register"), setError(""), setMessage(""), setLoading(false))}>Регистрация</button>
        <button  class="btn" onClick={() => (setAction("login"), setError(""), setMessage(""), setLoading(false))}>Вход</button>
        <form onSubmit={handleSubmit}>
          <div>
            <label>Email:</label>
            <input
                type="email"
                name="email"
                value={formData.email}
                onChange={handleChange}
                required
            />
          </div>
          <div>
            <label>Пароль:</label>
            <input
                type="password"
                name="password"
                value={formData.password}
                onChange={handleChange}
                required
            />
            <div>
              <button type="submit" class="search" disabled={loading || message || error}><span>{action === "register" ? "Зарегистрироваться" : "Войти"}</span></button>
            </div>
          </div>
        </form>
        {loading && <p>Загрузка...</p>}
        {message && <p style={{ color: "green" }}>{message}</p>}
        {error && <p style={{ color: "red" }}>{error}</p>}
        <footer>Сайт с олимпиадами 2025. Часть материалов была взята с сайта <a href="https://olimpiada.ru/" target="_blank">© Олимпиада.ру</a></footer>
    </div>
  );
};

export default Enter;
